import{_ as a,o as e,c as i,a6 as n}from"./chunks/framework.DL_pga9_.js";const k=JSON.parse('{"title":"Package Manager — MVP","description":"","frontmatter":{},"headers":[],"relativePath":"design/gap-package-manager.md","filePath":"design/gap-package-manager.md","lastUpdated":1781692128000}'),t={name:"design/gap-package-manager.md"};function l(p,s,r,h,o,d){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="package-manager-—-mvp" tabindex="-1">Package Manager — MVP <a class="header-anchor" href="#package-manager-—-mvp" aria-label="Permalink to “Package Manager — MVP”">​</a></h1><blockquote><p><strong>Status:</strong> Refined. Scope reduced to git+path dependencies only. Registry deferred.</p></blockquote><h2 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to “Order”">​</a></h2><p>Recommended implementation order: <strong>5</strong> (after tooling basics are stable).</p><h2 id="goal-mvp" tabindex="-1">Goal (MVP) <a class="header-anchor" href="#goal-mvp" aria-label="Permalink to “Goal (MVP)”">​</a></h2><p>Provide a minimal package manager for NG that handles <strong>git and path dependencies</strong> without a registry, lockfile, or publishing workflow.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to “Motivation”">​</a></h2><p>Even without a registry, the ability to depend on git repositories and local paths enables:</p><ul><li>Multi-project code organization</li><li>Sharing code via GitHub without manual copying</li><li>Reproducible builds via pinned commits</li></ul><h2 id="proposed-design" tabindex="-1">Proposed Design <a class="header-anchor" href="#proposed-design" aria-label="Permalink to “Proposed Design”">​</a></h2><h3 id="manifest-format-ng-toml" tabindex="-1">Manifest Format (<code>ng.toml</code>) <a class="header-anchor" href="#manifest-format-ng-toml" aria-label="Permalink to “Manifest Format (ng.toml)”">​</a></h3><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-app&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">version = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.1.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">entry = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;src/main.ng&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Git dependency (branch, tag, or commit)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">json = { git = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/user/json.ng&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, tag = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;v1.2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Path dependency (relative or absolute)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">my-lib = { path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;../libs/my-lib&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Short form (from default registry — future)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># http = &quot;0.2&quot;</span></span></code></pre></div><h3 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to “Commands”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # Create ng.toml interactively</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # Download all dependencies</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # Build project (resolves deps first)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                   # Build and run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # Update to latest matching version (git: latest commit on tag)</span></span></code></pre></div><h3 id="dependency-resolution-algorithm" tabindex="-1">Dependency Resolution Algorithm <a class="header-anchor" href="#dependency-resolution-algorithm" aria-label="Permalink to “Dependency Resolution Algorithm”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Input: ng.toml</span></span>
<span class="line"><span>Output: resolved dependency graph</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Parse ng.toml</span></span>
<span class="line"><span>2. For each dependency:</span></span>
<span class="line"><span>   a. If path: resolve from file system</span></span>
<span class="line"><span>   b. If git: git clone --depth 1 (or fetch if already cached)</span></span>
<span class="line"><span>3. Check for duplicate package names → error if different sources</span></span>
<span class="line"><span>4. Build module path order:</span></span>
<span class="line"><span>   - Project root first</span></span>
<span class="line"><span>   - Dependencies in insertion order</span></span>
<span class="line"><span>5. Write resolved paths to .ngmodules (generated config, not committed)</span></span></code></pre></div><h3 id="cache-structure" tabindex="-1">Cache Structure <a class="header-anchor" href="#cache-structure" aria-label="Permalink to “Cache Structure”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~/.ng/cache/</span></span>
<span class="line"><span>├── git/</span></span>
<span class="line"><span>│   ├── github.com_user_json.ng_v1.2.0/   # Cloned repository</span></span>
<span class="line"><span>│   │   ├── ng.toml</span></span>
<span class="line"><span>│   │   └── src/</span></span>
<span class="line"><span>│   └── github.com_user_http.ng_main/</span></span>
<span class="line"><span>└── download/                               # Future: registry packages</span></span></code></pre></div><p>Each git dependency is cloned once and cached by <code>(url + ref)</code>. The cache key is a hash of the URL and the git ref.</p><h3 id="lockfile-ngmodules" tabindex="-1">Lockfile (<code>.ngmodules</code>) <a class="header-anchor" href="#lockfile-ngmodules" aria-label="Permalink to “Lockfile (.ngmodules)”">​</a></h3><p>Simple generated file — not a full lockfile:</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Auto-generated by ng install. Do not commit.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/Users/user/projects/my-app&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">json = { path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/Users/user/.ng/cache/git/github.com_user_json.ng_v1.2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">my-lib = { path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/Users/user/projects/libs/my-lib&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>This maps dependency names to absolute paths. It&#39;s <code>.gitignore</code>-appropriate (machine-specific).</p><h3 id="module-path-integration" tabindex="-1">Module Path Integration <a class="header-anchor" href="#module-path-integration" aria-label="Permalink to “Module Path Integration”">​</a></h3><p>When <code>ng build</code> or <code>ng run</code> executes, it sets <code>NG_MODULE_PATH</code> to include all resolved dependency paths. This leverages the existing module resolution:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NG_MODULE_PATH = [</span></span>
<span class="line"><span>    project_root/src,</span></span>
<span class="line"><span>    /Users/user/.ng/cache/.../json,</span></span>
<span class="line"><span>    /Users/user/projects/libs/my-lib,</span></span>
<span class="line"><span>]</span></span></code></pre></div><p>The existing <code>ModuleLoader</code> already supports searching <code>NG_MODULE_PATH</code>. No changes needed to the module system.</p><h3 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to “Implementation”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>src/pkg/</span></span>
<span class="line"><span>├── Manifest.cpp/h      # ng.toml parsing</span></span>
<span class="line"><span>├── Resolver.cpp/h      # Dependency resolution</span></span>
<span class="line"><span>├── Cache.cpp/h         # ~/.ng/cache management</span></span>
<span class="line"><span>├── Git.cpp/h           # Git operations</span></span>
<span class="line"><span>├── CLI.cpp/h           # Command-line interface</span></span>
<span class="line"><span>└── Config.cpp/h        # Configuration</span></span></code></pre></div><h3 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to “Acceptance Criteria”">​</a></h3><ul><li><code>ng init</code> creates a valid <code>ng.toml</code> with name and entry</li><li><code>ng install</code> clones a git dependency and caches it</li><li><code>ng install [path]</code> copies/links a local dependency</li><li><code>ng build</code> with dependencies sets correct module paths</li><li>Duplicate dependency names produce a clear error</li><li>A project without <code>ng.toml</code> still works (backward compatible)</li></ul><h3 id="effort-estimate" tabindex="-1">Effort Estimate <a class="header-anchor" href="#effort-estimate" aria-label="Permalink to “Effort Estimate”">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Effort</th></tr></thead><tbody><tr><td>Manifest parsing (TOML)</td><td>1 week</td></tr><tr><td>Git integration (clone, fetch, cache)</td><td>2 weeks</td></tr><tr><td>Path dependency resolution</td><td>0.5 week</td></tr><tr><td>Module path integration</td><td>0.5 week</td></tr><tr><td>CLI interface</td><td>1 week</td></tr><tr><td>Tests</td><td>1 week</td></tr><tr><td><strong>Total</strong></td><td><strong>6 weeks</strong></td></tr></tbody></table><h3 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h3><ul><li>TOML parser for C++ (vendored: <code>toml11</code> or <code>cpptoml</code>)</li><li>Git CLI integration (can shell out to <code>git</code> command)</li><li>No changes to the existing module system</li></ul><h3 id="out-of-scope-mvp" tabindex="-1">Out of Scope (MVP) <a class="header-anchor" href="#out-of-scope-mvp" aria-label="Permalink to “Out of Scope (MVP)”">​</a></h3><ul><li>Registry / publishing</li><li>SemVer version resolution</li><li>Lockfile with hash verification</li><li>Dependency tree visualization</li><li>Authentication / private repos</li></ul>`,37)])])}const g=a(t,[["render",l]]);export{k as __pageData,g as default};
